/**
 * zephyrBrowserstackSync.mjs — SFCC-751 QA pipeline: BrowserStack Test
 * Observability -> Zephyr Scale execution sync, with automatic Jira defect
 * filing on failure.
 *
 * Invoked once per triggering QA workflow run, from
 * .github/workflows/zephyr-results-sync.yml. Not a check/gate — a sync job:
 * die() means the sync itself failed (the workflow step fails); a completed
 * run with zero Zephyr-tagged tests is a normal pass, not an error.
 *
 * Why this exists instead of BrowserStack's native Zephyr integration: that
 * integration's setup flow only accepts a Jira host, with no field for a
 * custom Zephyr API base URL — and this org's Zephyr Scale instance is
 * DE-hosted (https://de.api.zephyrscale.smartbear.com), not one of
 * BrowserStack's supported regions. See .docs/temp/SFCC-751-implementation-spec.md.
 *
 * Zephyr key mapping: reads each BrowserStack test result's `tags` array for
 * a `@zephyr:<KEY>` tag (confirmed via BrowserStack's Get Tests API to carry
 * real Playwright source-file tags, not synthesized ones). A result with no
 * such tag is skipped — not every spec participates in Zephyr sync.
 *
 * Evidence: Zephyr Scale's REST API has no attachment endpoint (confirmed —
 * four independent SmartBear community threads, ~2022-2024, nothing newer
 * found contradicting it). Evidence goes on the *Jira* defect instead;
 * Zephyr's execution `comment` field only gets a link to the BrowserStack
 * session and, if one was filed, the Jira defect.
 *
 * Assignee: the failing test's @SFCC-NNN story's current Jira assignee. If
 * unassigned, falls back to the last committer of the failing spec file
 * itself (git blame) — NOT the app code the test exercises, which isn't
 * derivable from a black-box E2E failure without deeper instrumentation;
 * a deliberately narrower, honest scope for the fallback. The spec file is
 * located by grepping for the test's title rather than trusting an assumed
 * BrowserStack response field for it (see NOT YET LIVE-VERIFIED below).
 *
 * NOT YET LIVE-VERIFIED: no BrowserStack build has ever existed under this
 * account's configured project (confirmed via a live GET /ext/v1/projects
 * call, 2026-08-25 — zero builds anywhere). getTestRuns() below now follows
 * the documented Get Tests response shape (a paginated `hierarchy[]` of
 * suites, each with `children[]` test entries under `details` — NOT a flat
 * `test_runs`/`tests` array, which the first version of this script wrongly
 * assumed and which would have silently synced zero results against a real
 * build) per https://www.browserstack.com/docs/test-reporting-and-analytics/api/get-tests,
 * cross-checked against a second independent source, 2026-08-25 — but still
 * not exercised against a real payload. Treat the first real run as the
 * actual verification, per Deliverable 3 of the implementation spec.
 *
 * Required env vars: BROWSERSTACK_USERNAME, BROWSERSTACK_ACCESS_KEY,
 * BROWSERSTACK_PROJECT_NAME, BROWSERSTACK_BUILD_NAME, ZEPHYR_API_KEY,
 * ZEPHYR_API_URL (base host + /testcases path; /testexecutions is derived
 * from it), JIRA_URL, JIRA_AUTOMATION_EMAIL, JIRA_AUTOMATION_API_TOKEN.
 * GITHUB_SERVER_URL/GITHUB_REPOSITORY/GITHUB_RUN_ID are supplied
 * automatically by Actions.
 */
import { execFileSync } from 'node:child_process';
import { appendFileSync } from 'node:fs';

const die = (msg) => {
  console.error(`✗ zephyr-browserstack-sync: ${msg}`);
  process.exit(1);
};
const warn = (msg) => console.error(`::warning::zephyr-browserstack-sync: ${msg}`);
const log = (msg) => console.log(`zephyr-browserstack-sync: ${msg}`);

const REQUIRED_ENV = [
  'BROWSERSTACK_USERNAME',
  'BROWSERSTACK_ACCESS_KEY',
  'BROWSERSTACK_PROJECT_NAME',
  'BROWSERSTACK_BUILD_NAME',
  'ZEPHYR_API_KEY',
  'ZEPHYR_API_URL',
  'JIRA_URL',
  'JIRA_AUTOMATION_EMAIL',
  'JIRA_AUTOMATION_API_TOKEN',
];
for (const key of REQUIRED_ENV) {
  if (!process.env[key]) die(`missing required env var ${key}`);
}

const {
  BROWSERSTACK_USERNAME,
  BROWSERSTACK_ACCESS_KEY,
  BROWSERSTACK_PROJECT_NAME,
  BROWSERSTACK_BUILD_NAME,
  ZEPHYR_API_KEY,
  ZEPHYR_API_URL,
  JIRA_URL,
  JIRA_AUTOMATION_EMAIL,
  JIRA_AUTOMATION_API_TOKEN,
  GITHUB_SERVER_URL,
  GITHUB_REPOSITORY,
  GITHUB_RUN_ID,
} = process.env;

const ZEPHYR_PROJECT_KEY = 'SFCC';
const ZEPHYR_TESTEXECUTIONS_URL = ZEPHYR_API_URL.replace(/\/testcases\/?$/, '/testexecutions');
const BROWSERSTACK_API = 'https://api-automation.browserstack.com';
const bstackAuth = 'Basic ' + Buffer.from(`${BROWSERSTACK_USERNAME}:${BROWSERSTACK_ACCESS_KEY}`).toString('base64');
const jiraAuth = 'Basic ' + Buffer.from(`${JIRA_AUTOMATION_EMAIL}:${JIRA_AUTOMATION_API_TOKEN}`).toString('base64');

/** Thin JSON-fetch wrapper — throws with the response body on a non-2xx status. */
async function fetchJson(url, opts = {}) {
  const res = await fetch(url, opts);
  const text = await res.text();
  let body;
  try {
    body = text ? JSON.parse(text) : {};
  } catch {
    body = text;
  }
  if (!res.ok) {
    throw new Error(`${opts.method || 'GET'} ${url} -> ${res.status}: ${JSON.stringify(body).slice(0, 300)}`);
  }
  return body;
}

async function findProjectId() {
  let page;
  do {
    const url = new URL(`${BROWSERSTACK_API}/ext/v1/projects`);
    if (page) url.searchParams.set('next_page', page);
    const { projects, pagination } = await fetchJson(url, { headers: { Authorization: bstackAuth } });
    const match = (projects || []).find((p) => p.name === BROWSERSTACK_PROJECT_NAME);
    if (match) return match.id;
    page = pagination?.has_next ? pagination.next_page : null;
  } while (page);
  return null;
}

async function findBuild(projectId) {
  const url = new URL(`${BROWSERSTACK_API}/ext/v1/projects/${projectId}/builds`);
  url.searchParams.set('unique_build_names', BROWSERSTACK_BUILD_NAME);
  const body = await fetchJson(url, { headers: { Authorization: bstackAuth } });
  const builds = body.builds || [];
  return builds[0] || null;
}

async function getTestRuns(buildId) {
  const tests = [];
  let page;
  do {
    const url = new URL(`${BROWSERSTACK_API}/ext/v1/builds/${buildId}/testRuns`);
    if (page) url.searchParams.set('next_page', page);
    const { hierarchy, pagination } = await fetchJson(url, { headers: { Authorization: bstackAuth } });
    for (const suite of hierarchy || []) {
      for (const child of suite.children || []) {
        const details = child.details || {};
        const failureLogs = (details.retries || []).flatMap((retry) => retry.logs?.TEST_FAILURE || []);
        tests.push({
          name: child.display_name,
          tags: details.tags || [],
          status: details.status,
          session_url: details.observability_url || null,
          error_message: failureLogs.join('\n') || null,
        });
      }
    }
    page = pagination?.has_next ? pagination.next_page : null;
  } while (page);
  return tests;
}

// BrowserStack's Test Observability API strips the leading '@' from
// Playwright tags — confirmed against a real local run's test_tags
// (2026-08-25): ['SFCC-751', 'homepage', 'p1', 'zephyr:SFCC-T285'], not
// ['@SFCC-751', ...]. The source spec files still carry '@'-prefixed tags
// (Playwright's own convention); only the API response has them stripped.
function zephyrKeyTag(tags) {
  const tag = (tags || []).find((t) => t.startsWith('zephyr:'));
  return tag ? tag.slice('zephyr:'.length) : null;
}

function storyKeyTag(tags) {
  const tag = (tags || []).find((t) => /^SFCC-\d+$/.test(t));
  return tag || null;
}

async function postZephyrExecution({ testCaseKey, statusName, comment }) {
  return fetchJson(ZEPHYR_TESTEXECUTIONS_URL, {
    method: 'POST',
    headers: { Authorization: `Bearer ${ZEPHYR_API_KEY}`, 'Content-Type': 'application/json' },
    body: JSON.stringify({ projectKey: ZEPHYR_PROJECT_KEY, testCaseKey, statusName, comment }),
  });
}

async function jiraStoryAssignee(storyKey) {
  try {
    const issue = await fetchJson(`${JIRA_URL}/rest/api/3/issue/${storyKey}?fields=assignee`, {
      headers: { Authorization: jiraAuth, Accept: 'application/json' },
    });
    return issue.fields?.assignee?.accountId || null;
  } catch (err) {
    warn(`could not read assignee for ${storyKey}: ${String(err.message).slice(0, 200)}`);
    return null;
  }
}

/** Last committer of the failing spec file — see the file-level doc comment
 * for why this stays scoped to the test file, not the app code under test. */
function findSpecFile(testName) {
  try {
    const out = execFileSync('grep', ['-rl', '--include=*.spec.js', '-F', testName, 'e2e/tests/zimm'], {
      encoding: 'utf8',
    }).trim();
    return out.split('\n')[0] || null;
  } catch {
    return null; // grep exits non-zero when nothing matches
  }
}

function gitBlameFallbackEmail(specPath) {
  try {
    return execFileSync('git', ['log', '-1', '--format=%ae', '--', specPath], { encoding: 'utf8' }).trim() || null;
  } catch (err) {
    warn(`git blame fallback failed for ${specPath}: ${err.message}`);
    return null;
  }
}

async function jiraAccountIdForEmail(email) {
  try {
    const users = await fetchJson(`${JIRA_URL}/rest/api/3/user/search?query=${encodeURIComponent(email)}`, {
      headers: { Authorization: jiraAuth, Accept: 'application/json' },
    });
    return users[0]?.accountId || null;
  } catch (err) {
    warn(`could not resolve Jira account for ${email}: ${String(err.message).slice(0, 200)}`);
    return null;
  }
}

async function resolveAssignee(storyKey, testName) {
  const storyAssignee = await jiraStoryAssignee(storyKey);
  if (storyAssignee) return storyAssignee;
  const specPath = findSpecFile(testName);
  const email = specPath ? gitBlameFallbackEmail(specPath) : null;
  return email ? jiraAccountIdForEmail(email) : null;
}

async function fileDefect({ storyKey, testName, sessionUrl, errorText, assigneeAccountId }) {
  const runUrl = `${GITHUB_SERVER_URL}/${GITHUB_REPOSITORY}/actions/runs/${GITHUB_RUN_ID}`;
  const body = {
    fields: {
      project: { key: ZEPHYR_PROJECT_KEY },
      issuetype: { name: 'Bug' },
      summary: `[Automated] BrowserStack failure: ${testName}`,
      description: {
        type: 'doc',
        version: 1,
        content: [
          {
            type: 'paragraph',
            content: [
              {
                type: 'text',
                text:
                  `Automatically filed from a BrowserStack E2E failure on ${storyKey}.\n\n` +
                  `BrowserStack session: ${sessionUrl || '(no session URL available)'}\n` +
                  `GitHub Actions run: ${runUrl}\n\n` +
                  `Error:\n${(errorText || '(no error text captured)').slice(0, 3000)}`,
              },
            ],
          },
        ],
      },
      // 'Relates' is Jira Cloud's common default link-type name — not
      // confirmed against this specific instance's configured types.
      issuelinks: [{ type: { name: 'Relates' }, outwardIssue: { key: storyKey } }],
      ...(assigneeAccountId ? { assignee: { accountId: assigneeAccountId } } : {}),
    },
  };
  return fetchJson(`${JIRA_URL}/rest/api/3/issue`, {
    method: 'POST',
    headers: { Authorization: jiraAuth, 'Content-Type': 'application/json' },
    body: JSON.stringify(body),
  });
}

function summaryLine(text) {
  if (process.env.GITHUB_STEP_SUMMARY) appendFileSync(process.env.GITHUB_STEP_SUMMARY, text + '\n');
  log(text);
}

async function main() {
  const projectId = await findProjectId();
  if (!projectId) die(`no BrowserStack project named '${BROWSERSTACK_PROJECT_NAME}' found`);

  const build = await findBuild(projectId);
  if (!build) {
    // e2e-browserstack is conditionally gated — many QA runs won't have
    // a BrowserStack build at all. That's expected, not an error.
    summaryLine(`No BrowserStack build named '${BROWSERSTACK_BUILD_NAME}' found — nothing to sync.`);
    return;
  }

  const testRuns = await getTestRuns(build.id);
  summaryLine(`## Zephyr sync — build \`${BROWSERSTACK_BUILD_NAME}\` (${testRuns.length} tests)`);
  summaryLine('| Test | Zephyr key | Status | Zephyr execution | Defect |');
  summaryLine('|---|---|---|---|---|');

  for (const test of testRuns) {
    const zephyrKey = zephyrKeyTag(test.tags);
    if (!zephyrKey) continue; // this spec doesn't participate in Zephyr sync

    const storyKey = storyKeyTag(test.tags);
    // Only map terminal statuses. BrowserStack Test Observability also
    // reports 'skipped'/'running'/'unknown' (e.g. a mobile-only spec's
    // desktop-project entry, or a still-in-progress run) — treating those
    // as 'Fail' would file false Zephyr failures and Jira defects for
    // tests that never actually ran or failed.
    if (test.status !== 'passed' && test.status !== 'failed') {
      summaryLine(`| ${test.name} | ${zephyrKey} | ${test.status} (skipped — non-terminal) | | |`);
      continue;
    }
    const statusName = test.status === 'passed' ? 'Pass' : 'Fail';
    const sessionUrl = test.session_url;

    let execution;
    try {
      execution = await postZephyrExecution({
        testCaseKey: zephyrKey,
        statusName,
        comment: `BrowserStack session: ${sessionUrl || '(unavailable)'}`,
      });
    } catch (err) {
      warn(`Zephyr execution POST failed for ${zephyrKey}: ${String(err.message).slice(0, 300)}`);
      summaryLine(`| ${test.name} | ${zephyrKey} | ${statusName} | **sync failed** | |`);
      continue;
    }

    if (statusName !== 'Fail' || !storyKey) {
      summaryLine(`| ${test.name} | ${zephyrKey} | ${statusName} | ${execution.key || execution.id} | |`);
      continue;
    }

    const assigneeAccountId = await resolveAssignee(storyKey, test.name);
    try {
      const defect = await fileDefect({
        storyKey,
        testName: test.name,
        sessionUrl,
        errorText: test.error_message || '',
        assigneeAccountId,
      });
      summaryLine(
        `| ${test.name} | ${zephyrKey} | ${statusName} | ${execution.key || execution.id} | ${JIRA_URL}/browse/${
          defect.key
        } |`,
      );
    } catch (err) {
      warn(`Jira defect creation failed for ${test.name}: ${String(err.message).slice(0, 300)}`);
      summaryLine(
        `| ${test.name} | ${zephyrKey} | ${statusName} | ${execution.key || execution.id} | **defect filing failed** |`,
      );
    }
  }
}

main().catch((err) => die(err.stack || err.message));

