    });
    return users[0]?.accountId || null;
  } catch (err) {
    warn(`could not resolve Jira account for ${email}: ${String(err.message).slice(0, 200)}`);
    return null;
  }
}

async function resolveAssignee(storyKey, testName) {
  const storyAssignee = await jiraStoryAssignee(storyKey);
  if (storyAssignee) return storyAssignee;
  const specPath = findSpecFile(testName);
  const email = specPath ? gitBlameFallbackEmail(specPath) : null;
  return email ? jiraAccountIdForEmail(email) : null;
}

async function fileDefect({ storyKey, testName, sessionUrl, errorText, assigneeAccountId }) {
  const runUrl = `${GITHUB_SERVER_URL}/${GITHUB_REPOSITORY}/actions/runs/${GITHUB_RUN_ID}`;
  const body = {
    fields: {
      project: { key: ZEPHYR_PROJECT_KEY },
      issuetype: { name: 'Bug' },
      summary: `[Automated] BrowserStack failure: ${testName}`,
      description: {
        type: 'doc',
        version: 1,
        content: [
          {
            type: 'paragraph',
            content: [
              {
                type: 'text',
                text:
                  `Automatically filed from a BrowserStack E2E failure on ${storyKey}.\n\n` +
                  `BrowserStack session: ${sessionUrl || '(no session URL available)'}\n` +
                  `GitHub Actions run: ${runUrl}\n\n` +
                  `Error:\n${(errorText || '(no error text captured)').slice(0, 3000)}`,
              },
            ],
          },
        ],
      },
      // 'Relates' is Jira Cloud's common default link-type name — not
      // confirmed against this specific instance's configured types.
      issuelinks: [{ type: { name: 'Relates' }, outwardIssue: { key: storyKey } }],
      ...(assigneeAccountId ? { assignee: { accountId: assigneeAccountId } } : {}),
    },
  };
  return fetchJson(`${JIRA_URL}/rest/api/3/issue`, {
    method: 'POST',
    headers: { Authorization: jiraAuth, 'Content-Type': 'application/json' },
    body: JSON.stringify(body),
  });
}

function summaryLine(text) {
  if (process.env.GITHUB_STEP_SUMMARY) appendFileSync(process.env.GITHUB_STEP_SUMMARY, text + '\n');
  log(text);
}

async function main() {
  const projectId = await findProjectId();
  if (!projectId) die(`no BrowserStack project named '${BROWSERSTACK_PROJECT_NAME}' found`);

  const build = await findBuild(projectId);
  if (!build) {
    // e2e-browserstack is conditionally gated — many QA runs won't have
    // a BrowserStack build at all. That's expected, not an error.
    summaryLine(`No BrowserStack build named '${BROWSERSTACK_BUILD_NAME}' found — nothing to sync.`);
    return;
  }

  const testRuns = await getTestRuns(build.id);
  summaryLine(`## Zephyr sync — build \`${BROWSERSTACK_BUILD_NAME}\` (${testRuns.length} tests)`);
  summaryLine('| Test | Zephyr key | Status | Zephyr execution | Defect |');
  summaryLine('|---|---|---|---|---|');

  for (const test of testRuns) {
    const zephyrKey = zephyrKeyTag(test.tags);
    if (!zephyrKey) continue; // this spec doesn't participate in Zephyr sync

    const storyKey = storyKeyTag(test.tags);
    // Only map terminal statuses. BrowserStack Test Observability also
    // reports 'skipped'/'running'/'unknown' (e.g. a mobile-only spec's
    // desktop-project entry, or a still-in-progress run) — treating those
    // as 'Fail' would file false Zephyr failures and Jira defects for
    // tests that never actually ran or failed.
    if (test.status !== 'passed' && test.status !== 'failed') {
      summaryLine(`| ${test.name} | ${zephyrKey} | ${test.status} (skipped — non-terminal) | | |`);
      continue;
    }
    const statusName = test.status === 'passed' ? 'Pass' : 'Fail';
    const sessionUrl = test.session_url;

    let execution;
    try {
      execution = await postZephyrExecution({
        testCaseKey: zephyrKey,
        statusName,
        comment: `BrowserStack session: ${sessionUrl || '(unavailable)'}`,
      });
    } catch (err) {
      warn(`Zephyr execution POST failed for ${zephyrKey}: ${String(err.message).slice(0, 300)}`);
      summaryLine(`| ${test.name} | ${zephyrKey} | ${statusName} | **sync failed** | |`);
      continue;
    }

    if (statusName !== 'Fail' || !storyKey) {
      summaryLine(`| ${test.name} | ${zephyrKey} | ${statusName} | ${execution.key || execution.id} | |`);
      continue;
    }

    const assigneeAccountId = await resolveAssignee(storyKey, test.name);
    try {
      const defect = await fileDefect({
        storyKey,
        testName: test.name,
        sessionUrl,
        errorText: test.error_message || '',
        assigneeAccountId,
      });
      summaryLine(
        `| ${test.name} | ${zephyrKey} | ${statusName} | ${execution.key || execution.id} | ${JIRA_URL}/browse/${
          defect.key
        } |`,
      );
    } catch (err) {
      warn(`Jira defect creation failed for ${test.name}: ${String(err.message).slice(0, 300)}`);
      summaryLine(
        `| ${test.name} | ${zephyrKey} | ${statusName} | ${execution.key || execution.id} | **defect filing failed** |`,
      );
    }
  }
}

main().catch((err) => die(err.stack || err.message));

