/**
 * computeBuildName.mjs — derives a human-readable BrowserStack build name
 * from a primary Jira key.
 *
 * Output shape (printed to stdout, nothing else): the suffix that plugs
 * directly into browserstack.yml's `buildName: "Sprint-${SPRINT_NUMBER}"`
 * template — e.g. for SPRINT_NUMBER="3-SFCC-751-SFCC-T285 - QA Pipeline —
 * Playwright spec…", the real build name becomes
 * "Sprint-3-SFCC-751-SFCC-T285 - QA Pipeline — Playwright spec…".
 *
 * Called only from qa.yml's e2e-browserstack job (which SETS
 * SPRINT_NUMBER, and so the real build name). zephyr-results-sync.yml does
 * NOT call this a second time — it downloads the exact string this job
 * computed as a build artifact instead. It used to recompute it
 * independently, but that job deliberately checks out develop rather than
 * the PR branch (see its own comment on why), so findZephyrKeys() below
 * would see a different e2e/tests/zimm spec-file set than this job's PR
 * checkout whenever a PR adds or renames a Zephyr-tagged spec — a
 * guaranteed mismatch while such a PR is open, not a rare race condition
 * (CodeRabbit flagged this correctly, 2026-08-25; an earlier version of
 * this comment mischaracterised the risk as a rare same-issue-changes-
 * mid-flight race). Artifact-passing removes the drift instead of just
 * accepting it.
 *
 * Usage: node scripts/computeBuildName.mjs <JIRA_KEY>
 * Requires: JIRA_URL, JIRA_AUTOMATION_EMAIL, JIRA_AUTOMATION_API_TOKEN
 *
 * Never fails the caller — a Jira lookup problem degrades to a plainer
 * name (e.g. "unknown-SFCC-751") rather than blocking a test run that has
 * nothing to do with build-name cosmetics.
 */
import { execFileSync } from 'node:child_process';

// Confirmed live via a real jira_search_fields call against this Jira
// instance (2026-08-25) — Jira Cloud has no stable "sprint" field alias;
// this customfield ID is instance-specific, not a safe value to assume
// for any other Jira site.
const SPRINT_FIELD = 'customfield_10020';
const MAX_SUMMARY_LEN = 40;

const [jiraKey] = process.argv.slice(2);
if (!jiraKey) {
  console.error('usage: computeBuildName.mjs <JIRA_KEY>');
  process.exit(1);
}

function fallback(reason) {
  console.error(`computeBuildName: ${reason} — falling back to a plain name`);
  console.log(`unknown-${jiraKey}`);
  process.exit(0);
}

const { JIRA_URL, JIRA_AUTOMATION_EMAIL, JIRA_AUTOMATION_API_TOKEN } = process.env;
if (!JIRA_URL || !JIRA_AUTOMATION_EMAIL || !JIRA_AUTOMATION_API_TOKEN) {
  fallback('missing JIRA_URL/JIRA_AUTOMATION_EMAIL/JIRA_AUTOMATION_API_TOKEN');
}

function truncate(text, max) {
  return text.length > max ? `${text.slice(0, max - 1).trimEnd()}…` : text;
}

/** Zephyr key(s) tagged on any spec that also carries this Jira key's tag —
 * greps the same way scripts/zephyrBrowserstackSync.mjs locates a spec by
 * test name, since there's no other cross-reference between a story and
 * its Zephyr case(s). */
function findZephyrKeys() {
  let files;
  try {
    files = execFileSync('grep', ['-rlF', `@${jiraKey}`, '--include=*.spec.js', 'e2e/tests/zimm'], {
      encoding: 'utf8',
    })
      .trim()
      .split('\n')
      .filter(Boolean);
  } catch {
    return []; // grep exits non-zero when nothing matches — no spec for this key yet
  }
  const keys = new Set();
  for (const file of files) {
    try {
      execFileSync('grep', ['-ohE', '@zephyr:[A-Z]+-T[0-9]+', file], { encoding: 'utf8' })
        .trim()
        .split('\n')
        .filter(Boolean)
        .forEach((m) => keys.add(m.slice('@zephyr:'.length)));
    } catch {
      // this file has no @zephyr: tag — fine, not every spec participates
    }
  }
  return [...keys];
}

async function main() {
  const jiraAuth = 'Basic ' + Buffer.from(`${JIRA_AUTOMATION_EMAIL}:${JIRA_AUTOMATION_API_TOKEN}`).toString('base64');
  let issue;
  try {
    const res = await fetch(`${JIRA_URL}/rest/api/3/issue/${jiraKey}?fields=summary,${SPRINT_FIELD}`, {
      headers: { Authorization: jiraAuth, Accept: 'application/json' },
    });
    if (!res.ok) throw new Error(`HTTP ${res.status}`);
    issue = await res.json();
  } catch (err) {
    fallback(`Jira lookup failed for ${jiraKey}: ${err.message}`);
    return;
  }

  // Raw REST API returns a plain array; some callers (e.g. an MCP tool) may
  // normalize it as {value: [...]} — handle both rather than trust one shape.
  const sprintField = issue.fields?.[SPRINT_FIELD];
  const sprintEntry = Array.isArray(sprintField) ? sprintField[0] : sprintField?.value?.[0];
  const sprintMatch = (sprintEntry?.name || '').match(/(\d+)\s*$/);
  const sprintNum = sprintMatch ? sprintMatch[1] : 'unknown';

  const zephyrKeys = findZephyrKeys();
  const summary = truncate(issue.fields?.summary || '', MAX_SUMMARY_LEN);

  const parts = [sprintNum, jiraKey, ...zephyrKeys].join('-');
  console.log(summary ? `${parts} - ${summary}` : parts);
}

main();

