/*
 * Deliberately a separate file/title from
 * ../desktop/SFCC-751_header-nav-site-prefix.spec.js, not a mobile
 * variant of the same test. BrowserStack Test Observability groups
 * results by test title across "reruns" regardless of Playwright project
 * — a shared title running on both chromium and mobile-chrome collapses
 * to one row showing only the last-recorded status, hiding whichever one
 * didn't "win" (confirmed against real build data, 2026-08-25). This
 * file's location under mobile/ means chromium's own testIgnore in
 * playwright.config.js never collects it at all — true separation, not a
 * runtime skip, which is what actually avoids the collision (a same-file,
 * distinct-title approach was tried and rejected — the underlying test()
 * call still gets collected, and skipped, on the other project either
 * way).
 *
 * No @zephyr: tag — SFCC-T285 covers the desktop scenario this pipeline
 * was built to validate; this gap has no Zephyr test case of its own yet.
 */

const { test, expect } = require('@playwright/test');
const { MobileDrawerMenuPage } = require('../../../../support/pages/MobileDrawerMenuPage');
const { activeSiteKey } = require('../../../../fixtures/site');
const sitePrefixes = require('../../../../fixtures/sitePrefixes');

test.describe('Mobile header navigation', () => {
  test(
    'Mobile header nav exposes site-prefixed category browsing links',
    { tag: ['@SFCC-751', '@homepage', '@p1'] },
    async ({ page }) => {
      const drawerMenu = new MobileDrawerMenuPage(page);
      await drawerMenu.goToSite(sitePrefixes[activeSiteKey()].urlPrefix);

      // Expected to fail today: the mobile drawer currently has no
      // category navigation content at all (only account/store-locator
      // links — confirmed 2026-08-25). A known, already-documented gap
      // against HPC-018 in overrides/app/components/header/index.tsx's
      // own comments, not introduced by this spec. This test exists to
      // make that gap visible in CI rather than silently untested, and
      // should start passing on its own once mobile category nav ships.
      const hrefs = await drawerMenu.getDrawerLinkHrefs();
      const categoryHrefs = hrefs.filter((href) => href.includes('/category/'));
      expect(categoryHrefs.length).toBeGreaterThan(0);
    },
  );
});

